export default "<!doctype html>\n<html lang=\"ru\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Gene Atlas — проверка аннотаций</title>\n<style>\n:root{color-scheme:light;--ink:#173425;--muted:#526257;--line:#d7dbd0;--paper:#f8f7f1;--green:#28583a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,sans-serif}header{border-bottom:1px solid var(--line)}.bar,main{max-width:1280px;margin:auto;padding-inline:clamp(18px,5vw,64px)}.bar{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand,h1,h2{font-family:Georgia,serif}.brand{font-size:24px}main{padding-block:46px 60px}h1{font-size:clamp(36px,6vw,68px);margin:0;line-height:1.08;letter-spacing:-.045em}h2{font-size:25px;margin:0}p{color:var(--muted)}.intro{font-size:18px;margin:12px 0 24px}form,.examples,.pagination{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,input{font:inherit;border-radius:8px;padding:10px 14px}button{cursor:pointer;background:#fffdf8;color:var(--ink);border:1px solid var(--line)}button:hover:not(:disabled){background:#e9eee3}button:disabled{opacity:.5;cursor:default}input{border:1px solid #aab6a9;background:#fffdf8;flex:1;min-width:140px;max-width:420px}.primary{background:var(--green);color:white;border-color:var(--green);font-weight:650}.primary:hover:not(:disabled){background:#356f4b}.examples{margin-top:12px;color:var(--muted)}.examples button{padding:3px 9px}.panel{margin-top:24px;border:1px solid var(--line);border-radius:14px;background:#fffdf8;overflow:hidden}.panel-head{padding:18px 20px}.wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:620px;text-align:left}th,td{padding:12px 18px;border-top:1px solid var(--line);vertical-align:top}th{background:#eeeee5;font-size:13px}td:first-child{width:35%}td:last-child{width:26%}td small{display:block;color:var(--muted)}a{color:#255d40;text-underline-offset:3px}.state{display:inline-block;background:#f2eee2;border-radius:20px;padding:3px 9px;font-size:12px}.verified{background:#e2efdf;color:#214e31}.pagination{padding:13px 18px;border-top:1px solid var(--line)}.journal{padding:19px 20px;background:#eef1e8}.journal p{margin:7px 0 0}.journal ol{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;padding:0;list-style:none;margin:12px 0 0}.journal li{border-left:2px solid #9bb19c;padding-left:10px;min-width:0}.journal pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:15rem;overflow:auto}summary{cursor:pointer}#message{min-height:24px;margin:14px 0 0}.error{color:#9d3925}dialog{width:min(540px,calc(100vw - 32px));border:1px solid var(--line);border-radius:16px;padding:24px;background:#fffdf8;color:var(--ink)}dialog::backdrop{background:#12271d77}.candidate{padding:10px 0;border-top:1px solid var(--line)}button:focus-visible,input:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #398859;outline-offset:3px}[hidden]{display:none!important}@media(max-width:600px){main{padding-top:28px}.bar{min-height:58px}.panel-head,.journal{padding:14px}}\n.summary{background:#eef3e8;border-color:#cbd8c8}.summary p{margin:7px 0}.summary .role-note{font-size:14px}.summary #summary-text{color:var(--ink)}\n.journal ol{display:block;margin-top:18px}.journal li{padding:0 0 16px 18px;position:relative}.journal li::before{content:'';position:absolute;top:6px;left:-5px;width:8px;height:8px;border-radius:50%;background:var(--green)}.journal li p{font-size:13px;margin:1px 0 4px}.journal summary{font-size:13px;color:var(--green)}\n</style>\n<header><div class=\"bar\"><strong class=\"brand\">Gene Atlas</strong><button id=\"csv\" disabled>Скачать CSV ↓</button></div></header>\n<main>\n<h1>Проверка аннотаций гена</h1>\n<p class=\"intro\">Введите ген, чтобы понять, какие записи Ensembl уже привязаны к стандартным терминам HPO и где сопоставление нужно проверить вручную.</p>\n<form id=\"search\"><input id=\"symbol\" aria-label=\"Символ гена\" placeholder=\"Например, FBN1\" maxlength=\"25\" required><button class=\"primary\">Проверить</button></form>\n<div class=\"examples\">Примеры <button type=\"button\">FBN1</button><button type=\"button\">CFTR</button></div>\n<p id=\"message\" role=\"status\"></p>\n<section id=\"review-summary\" class=\"panel panel-head summary\" hidden>\n<h2 id=\"gene-heading\">О гене</h2>\n<p id=\"gene-description\"></p>\n<p id=\"gene-explanation\"></p>\n<small id=\"gene-note\" hidden>Справочное описание функции подготовлено моделью. Ссылка Ensembl ведёт на исходную карточку гена.</small>\n<p id=\"gene-source\"></p>\n<p id=\"summary-text\" class=\"role-note\"></p>\n</section>\n<section id=\"results\" class=\"panel\" hidden>\n<div class=\"panel-head\"><h2 id=\"heading\"></h2><div id=\"range\"></div></div>\n<div class=\"wrap\"><table><thead><tr><th>Запись Ensembl</th><th>Термины HPO</th><th>Статус</th></tr></thead><tbody id=\"rows\"></tbody></table></div>\n\n</section>\n<section class=\"panel journal\"><h2>Как работали агенты</h2><p id=\"hint\">Запустите проверку, чтобы увидеть обмен данными.</p><ol id=\"events\" aria-live=\"polite\"></ol></section>\n</main>\n<dialog id=\"review\"><h2 id=\"review-title\">Выберите термин</h2><div id=\"candidates\"></div><form method=\"dialog\"><button>Закрыть</button></form></dialog>\n<script type=\"module\">\nconst get = id => document.getElementById(id);\nconst chooseButtons = [...document.querySelectorAll('.examples button')];\nlet current;\nlet busy = false;\n\nfunction add(parent, tag, text) {\n  const element = document.createElement(tag);\n  element.textContent = text;\n  parent.append(element);\n  return element;\n}\nfunction link(parent, label, url) {\n  const anchor = add(parent, 'a', label);\n  anchor.href = url;\n  anchor.target = '_blank';\n  anchor.rel = 'noopener noreferrer';\n}\nfunction log({from, to, summary, data}) {\n  const box = add(get('events'), 'li', '');\n  add(box, 'strong', summary);\n  add(box, 'p', from + ' → ' + to);\n  const detail = add(box, 'details', '');\n  add(detail, 'summary', 'Данные сообщения');\n  add(detail, 'pre', JSON.stringify(data, null, 2));\n  get('hint').hidden = true;\n}\nfunction openReview(row) {\n  get('review-title').textContent = row.title;\n  const candidates = get('candidates');\n  candidates.replaceChildren();\n  for (const term of row.terms) {\n    const block = add(candidates, 'div', '');\n    block.className = 'candidate';\n    link(block, term.label + ' · ' + term.id, term.url);\n    if (term.description) add(block, 'p', term.description);\n    const button = add(block, 'button', term.id === row.recommended ? 'Подтвердить предложенный термин' : 'Выбрать термин');\n    button.onclick = () => commitChoice(row, term);\n  }\n  if (row.selected) add(candidates, 'button', 'Снять подтверждение').onclick = () => commitChoice(row, null);\n  get('review').showModal();\n}\nfunction commitChoice(row, term) {\n  row.selected = term;\n  log({from:'Пользователь',to:'Таблица',summary:term ? 'Термин подтверждён вручную' : 'Подтверждение снято',data:{record:row.title,hpo:term?.id || null}});\n  get('review').close();\n  render();\n}\nfunction render() {\n  const result = current;\n  get('results').hidden = !result;\n  get('review-summary').hidden = !result?.summary;\n  get('summary-text').textContent = result?.summary || '';\n  const gene = result?.geneProfile;\n  get('gene-heading').textContent = result ? 'О гене ' + result.gene : 'О гене';\n  get('gene-description').textContent = gene?.description || '';\n  get('gene-explanation').textContent = gene?.explanation || '';\n  get('gene-note').hidden = !gene?.explanation;\n  get('gene-source').replaceChildren();\n  if (gene?.url) link(get('gene-source'), 'Карточка гена в Ensembl ↗', gene.url);\n  get('csv').disabled = busy || !result?.rows.length;\n  if (!result) return;\n  get('heading').textContent = 'Аннотации ' + result.gene;\n  get('range').textContent = result.rows.length\n    ? 'Записей: ' + result.total + ' · ' + result.geneId\n    : 'Ensembl не вернул аннотаций.';\n  const table = get('rows');\n  table.replaceChildren();\n  for (const row of result.rows) {\n    const tr = add(table, 'tr', '');\n    const original = add(tr, 'td', '');\n    link(original, row.title, row.url);\n    if (row.source) add(original, 'small', row.source);\n    const terms = add(tr, 'td', '');\n    if (row.ids.length || row.selected) {\n      const shown = row.selected ? [row.selected] : row.terms;\n      for (const term of shown.slice(0, 3)) link(add(terms, 'div', ''), term.label + ' · ' + term.id, term.url);\n      if (shown.length > 3) {\n        const more = add(terms, 'details', '');\n        add(more, 'summary', 'Ещё терминов: ' + (shown.length - 3));\n        for (const term of shown.slice(3)) link(add(more, 'div', ''), term.label + ' · ' + term.id, term.url);\n      }\n      if (row.ids.length > row.terms.length) add(terms, 'small', 'Проверено ' + row.terms.length + ' из ' + row.ids.length + ' ID');\n    }\n    if (!row.ids.length && row.terms.length) {\n      const button = add(terms, 'button', row.selected ? 'Изменить' : 'Выбрать термин →');\n      button.disabled = busy;\n      button.onclick = () => openReview(row);\n    } else if (!row.ids.length) terms.textContent = '—';\n    const state = add(add(tr, 'td', ''), 'span', row.selected ? 'Подтверждено вручную' : row.status);\n    state.className = 'state' + (row.selected || row.status === 'Совпадение по ID' ? ' verified' : '');\n  }\n}\nasync function check(symbol) {\n  if (busy) return;\n  current = null;\n  get('events').replaceChildren();\n  get('hint').hidden = false;\n  busy = true;\n  render();\n  get('search').querySelector('button').disabled = true;\n  chooseButtons.forEach(button => { button.disabled = true; });\n  const message = get('message');\n  message.className = '';\n  message.textContent = 'Проверяем ' + symbol + '…';\n  try {\n    const response = await fetch('/audit', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol})});\n    if (!response.ok) throw Error(await response.text());\n    let buffer = '';\n    let result;\n    for await (const chunk of response.body.pipeThrough(new TextDecoderStream())) {\n      buffer += chunk;\n      const lines = buffer.split('\\n');\n      buffer = lines.pop();\n      for (const line of lines) {\n        const event = JSON.parse(line);\n        if (event.error) throw Error(event.error);\n        if (event.message) {\n          log(event.message);\n          message.textContent = event.message.summary;\n        }\n        if (event.result) result = event.result;\n      }\n    }\n    if (!result) throw Error('Сервер не вернул результат.');\n    current = result;\n    message.textContent = '';\n  } catch (error) {\n    message.className = 'error';\n    message.textContent = error.message;\n  } finally {\n    busy = false;\n    get('search').querySelector('button').disabled = false;\n    chooseButtons.forEach(button => { button.disabled = false; });\n    render();\n  }\n}\nget('search').onsubmit = event => {\n  event.preventDefault();\n  check(get('symbol').value.trim().toUpperCase());\n};\nfor (const button of chooseButtons) button.onclick = () => {\n  get('symbol').value = button.textContent;\n  get('search').requestSubmit();\n};\nget('csv').onclick = () => {\n  const rows = [['Ensembl ID','Аннотация','Поставщик','HPO ID в Ensembl','Проверенные HPO ID','Подтверждён вручную','Статус','Ensembl URL','HPO URL']];\n  for (const row of current.rows) rows.push([current.geneId,row.title,row.source,row.ids.join(' | '),\n      row.ids.length ? row.terms.map(term => term.id).join(' | ') : '',row.selected?.id,\n      row.selected ? 'Подтверждено вручную' : row.status,row.url,\n      row.selected?.url || (row.ids.length ? row.terms.map(term => term.url).join(' | ') : '')]);\n  const escape = value => {\n    const text = String(value ?? '');\n    return '\"' + (/^[=+\\-@\\t\\r]/.test(text) ? \"'\" : '') + text.replaceAll('\"','\"\"') + '\"';\n  };\n  const url = URL.createObjectURL(new Blob(['\\uFEFF' + rows.map(row => row.map(escape).join(',')).join('\\r\\n')],{type:'text/csv;charset=utf-8'}));\n  const download = document.createElement('a');\n  download.href = url;\n  download.download = current.gene + '-annotations.csv';\n  download.click();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n};\n</script>\n</html>\n";
